+// Sites: kitchens that share items, suppliers, recipes and dishes but keep
+// their own locations, and so their own batches (docs/DATA.md).
+import { AppError } from "../errors.js";
+
+export const DEFAULT_SITE = "main";
+
+/** One site, or AppError unknown_site. */
+export function getSite(store, id) {
+  const site = (store.data.sites ?? []).find((s) => s.id === id);
+  if (!site) throw new AppError("unknown_site", { id });
+  return site;
+}
+
+/** Locations of a site (all locations when `site` is undefined). */
+export function siteLocations(store, site) {
+  return store.data.locations.filter((l) => site === undefined || l.site === site);
+}
+
+/** True when a batch is stored in a location of `site` (always true when `site` is undefined). */
+export function batchInSite(store, batch, site) {
+  return site === undefined || store.data.locations.some((l) => l.id === batch.location && l.site === site);
+}
+
+/** Batches stored in a site's locations (all batches when `site` is undefined). */
+export function siteBatches(store, site) {
+  return store.data.batches.filter((b) => batchInSite(store, b, site));
+}
